class Solution {
public:
    double minimumAverage(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        double ans = 1e9;
        for (int i = 0; i < n / 2; ++i) {
            ans = min(ans, (nums[i] + nums[n - 1 - i]) / 2.0);
        }
        return ans;
    }
};

class Solution {
    public double minimumAverage(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length;
        double ans = Double.MAX_VALUE;
        for (int i = 0; i < n / 2; ++i) {
            ans = Math.min(ans, (nums[i] + nums[n - 1 - i]) / 2.0);
        }
        return ans;
    }
}

var minimumAverage = function(nums) {
    nums.sort((a, b) => a - b);
    const n = nums.length;
    let ans = Infinity;
    for (let i = 0; i < Math.floor(n / 2); ++i) {
        ans = Math.min(ans, (nums[i] + nums[n - 1 - i]) / 2);
    }
    return ans;
};
